#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=11

cd "$(git rev-parse --show-toplevel)"
banner "Tableau Public companion (ticket 17)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Export fresh data from Snowflake"
say "The CSVs in tableau/out/ predate the full backfill. Re-export from the"
say "current Publication through the read-only dashboard role."
note "Runs: uv run --env-file .env python -m tableau.export"
if confirm "Run the export now?"; then
  if ! uv run --env-file .env python -m tableau.export; then
    warn "Export failed. Check SNOWFLAKE_* in .env, then re-run this wizard."
    exit 1
  fi
else
  warn "Using the existing CSVs in tableau/out/."
fi
say ""
say "Coverage of this export:"
column -s, -t < tableau/out/nyc311_coverage.csv | sed 's/^/    /'
note "first_created_date should be 2025-01-01 or close; if it's 2026-09-01 the backfill isn't published yet."
pause "Looks right? Press Enter"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Tableau Public account and desktop app"
open_url "https://public.tableau.com"
step "Sign up (free) or sign in. Remember your profile name."
open_url "https://www.tableau.com/products/public/download"
step "Download Tableau Public (the desktop app), install it, open it, sign in."
pause "Tableau Public open and signed in? Press Enter"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Connect the two CSVs"
open tableau/out 2>/dev/null || note "Files are in $(pwd)/tableau/out"
step "Connect → To a File → Text file → tableau/out/nyc311_daily.csv"
step "Data Source tab: created_date = Date; requests, closed_requests, open_requests = Number (whole)."
step "Rename fields to title case: Created Date, Borough, Agency, Problem, Channel, Requests, Closed Requests, Open Requests."
step "Data → New Data Source → Text file → tableau/out/nyc311_coverage.csv (used only for the 'as of' caption)."
pause "Both sources connected? Press Enter"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Calculated fields (on nyc311_daily)"
say "Analysis → Create Calculated Field, one per row:"
step "Closure Rate     = SUM([Closed Requests]) / SUM([Requests])   → format % with 1 decimal"
step "Open Share       = SUM([Open Requests]) / SUM([Requests])"
step "Enough Requests  = SUM([Requests]) >= 20"
pause "Three fields created? Press Enter"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Sheets 1–2: KPIs and Requests per day"
step "Sheet 'KPIs': Measure Names on Columns, Measure Values on Text."
note "  Keep only Requests, Closed Requests, Open Requests, Closure Rate. Make the numbers large."
step "Sheet 'Requests per day': DAY(Created Date) on Columns; Measure Values on Rows."
note "  Keep Closed Requests and Open Requests; stacked bars; Measure Names on Color."
note "  Colors: Closed #2a78d6 (blue), Open #eb6834 (orange), matching Streamlit."
pause "Done? Press Enter"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Sheets 3–4: By borough and Top Problems"
step "Sheet 'By borough': Borough on Rows, SUM(Requests) horizontal bars sorted descending, Closure Rate on Label."
step "Sheet 'Top Problems': Problem on Rows, SUM(Requests) bars."
note "  Filter Problem → Top → By field: Top 15 by SUM(Requests). Closure Rate on Color."
pause "Done? Press Enter"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Sheets 5–6: Agency × borough heatmap and Channel mix"
step "Sheet 'Agency × borough': Agency on Rows, Borough on Columns, Square marks, Closure Rate on Color."
step "  Drag Enough Requests to Filters → keep True (hides cells under 20 Requests)."
step "Sheet 'Channel mix': Borough on Rows, SUM(Requests) on Columns, Channel on Color."
note "  SUM(Requests) → Quick Table Calculation → Percent of Total, Compute Using → Channel."
pause "Done? Press Enter"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Sheet 7: As of caption"
step "New sheet 'As of', using the nyc311_coverage source."
step "Put first_created_date, last_created_date, latest_extracted_at_new_york on Text, then edit the text to:"
note "  Created <first_created_date> to <last_created_date> · data as of <latest_extracted_at_new_york> New York time"
pause "Done? Press Enter"

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Dashboard layout and filters"
step "New Dashboard. Size → Automatic (or 1200 × 900)."
step "Title: NYC 311 Signal: Requests and Closure"
step "Top row: KPIs + As of. Then Requests per day full width."
step "Then By borough | Top Problems, then Agency × borough | Channel mix."
step "Show filters: Created Date (range), Borough, Agency, Problem (multi-select dropdown)."
step "On each filter: Apply to Worksheets → All Using This Data Source."
pause "Done? Press Enter"

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Actions, tooltips and caption"
say "Dashboard → Actions:"
step "Filter: source By borough → all sheets, Run on Select."
step "Filter: source Top Problems → Requests per day + Agency × borough, Run on Select."
step "Highlight: source Channel mix, Run on Hover."
step "Rewrite each tooltip in plain words, e.g. '<Requests> Requests created in <Borough>, <Closure Rate> Closed so far'."
step "Add a Text box caption:"
note "  Counts of NYC 311 Service Requests by creation date. Closed is the administrative"
note "  Closure recorded by the source, not proof the problem was fixed. No addresses or"
note "  locations below borough."
step "Check: click a borough, the whole dashboard filters; heatmap shows no cells under 20 Requests."
pause "Done? Press Enter"

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Publish to Tableau Public"
warn "Everything saved to Tableau Public is public. The export holds counts only (ADR 0002)."
if confirm "Publish now?"; then
  step "File → Save to Tableau Public As… → name it 'NYC 311 Signal'."
  step "When the browser opens the published viz, copy its URL."
  while true; do
    ask TABLEAU_PUBLIC_URL "Paste the workbook URL:"
    [[ "$TABLEAU_PUBLIC_URL" == https://public.tableau.com/* ]] && break
    warn "Expected a https://public.tableau.com/... URL."
  done
  write_env TABLEAU_PUBLIC_URL "$TABLEAU_PUBLIC_URL"
else
  SKIPPED+=("Publish to Tableau Public, then re-run this wizard to record the URL")
fi

finish
say "Next: hand the URL to Claude to link it in README and close ticket 17."
}

run_wizard "$@"; exit
